/* From Uiverse.io by R0G3RF4 - Tags: facebook, button */
.__UIV_SCOPE__ button {
  background: transparent;
  position: relative;
  padding: 5px 15px;
  display: flex;
  align-items: center;
  font-size: 17px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  border: 1px solid #0163E0;
  border-radius: 25px;
  outline: none;
  overflow: hidden;
  color: #0163E0;
  transition: color 0.3s 0.1s ease-out;
  text-align: center;
}

.__UIV_SCOPE__ button svg {
  fill: #0163E0;
  height: 25px;
  width: 25px;
}

.__UIV_SCOPE__ button span {
  margin: 10px;
}

.__UIV_SCOPE__ button::before {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  margin: auto;
  content: '';
  border-radius: 50%;
  display: block;
  width: 20em;
  height: 20em;
  left: -5em;
  text-align: center;
  transition: box-shadow 0.5s ease-out;
  z-index: -1;
}

.__UIV_SCOPE__ button:hover {
  color: #fff;
  border: 1px solid #0163E0;
}

.__UIV_SCOPE__ button:hover svg {
  fill: currentColor;
}

.__UIV_SCOPE__ button:hover::before {
  box-shadow: inset 0 0 0 10em #0163E0;
}
